    text: `Великое искусство заключается в том, чтобы разделить внутреннее и внешнее. Внутри вас происходит лишь беспристрастное восприятие ощущений и переживаний, а на внешнем плане вы можете совершенно спокойно совершать действия, оценивать ситуации и решать проблемы. Ваша оценка должна быть лишь фоновой мыслью, которая при необходимости провоцирует адекватное внешнее действие, но не превращается во внутреннюю рефлексию и эмоциональное втягивание.`,
    source: "Хочу Ясности",
    tags: ["мудрость", "рекомендации"]
