    text: `Эго — это не объект и не сущность, а иллюзия «я-идеи». Его невозможно найти или убить, так как оно никогда не существовало как реальный субъект. Избавление от эго происходит только через видение того, что эта идея является иллюзией.`,
    source: "Хочу Ясности",
    tags: ["наблюдения", "мудрость"]
