    number: 349,
    text: `Настоящая медитация происходит в тотальном безусилии, когда отсутствует деятель и делание. Если возникает ощущение напряжения или энергозатрат — вы идете не туда. Просто выдохните, расслабьтесь и разожмите все, что удерживаете.`,
