    number: 362,
    text: `Когда сознание теряет способность к критическому анализу и прямому видению сути, ум становится объектом манипуляции внешних форм. Люди покупают не качество, а иллюзию, созданную искусно упакованными концепциями, потому что предпочитают верить авторитетам и ярким картинкам, вместо того чтобы исследовать состав вещей самостоятельно. Деградация интеллекта — это потеря контакта с реальностью, где человек перекладывает ответственность за свою жизнь на тех, кто умеет красиво продавать миражи.`,
