    number: 365,
    text: `Не уподобляйтесь тем, кто слепо следует формальным практикам из-за страха или авторитета. Используйте интеллект, данный природой, для глубокого размышления. Духовный поиск требует не механического повторения действий, а живого исследования того, на что на самом деле указывает понятие «мое».`,
