    number: 366,
    text: `Реальный поиск начинается только в момент глубокого прозрения о том, что вы не знаете, кто вы есть на самом деле. Это состояние сродни амнезии: когда вы осознаете, что не помните свою природу, вас начинает буквально выворачивать наизнанку от невозможности жить в привычных рамках. Если внутри нет этого жгучего, раздирающего незнания, ваш поиск — лишь интеллектуальное любопытство и пустая болтовня.`,
