    number: 368,
    text: `Ощутите это состояние: если бы вы проснулись и не помнили, кто вы, вы не смогли бы жить дальше, не выяснив этого. Истинный духовный голод — это когда вам физически невыносимо не знать свою природу. Пока у вас есть «нормальное» состояние, в котором вы комфортно чувствуете себя как личность, любое любопытство о природе реальности остается лишь игрой ума.`,
