    number: 381,
    text: `Вся гора информации от учителей и методов служит лишь двум вещам: осознать, что такое просветление, и найти ту единственную фразу или понимание, которое удерживает вас в этой ясности. Просветление часто случается не от накопления знаний, а от одной фразы, которую человек носит в своем сердце и переживании всю жизнь.`,
