    text: `Обычное мышление всегда подменяет выбор между истиной и ложью выбором между двумя формами лжи. Выбор между желаниями, целями или методами — это всегда выбор внутри иллюзии. Сам факт того, что вы находитесь в состоянии выбора, свидетельствует о потере видения своей истинной природы.`,
