    text: `Суть практики в том, чтобы увидеть: любое событие, ощущение или мысль автоматически окрашиваются чувством, что «это происходит со мной». Это чувство — лишь еще одно ощущение, которое также нужно увидеть и оставить в покое. Все просто происходит само по себе.`,
