    number: 555,
    text: `Личность — это не реальная сущность, а концептуальный сгусток, набор характеристик и образов, от лица которых идет общение с миром. Мы прекрасно понимаем, что никакой личности нет, поэтому говорить о ее существовании — это смешно.`,
