    text: `Важно уметь различать сущностные указания от формы их подачи. Иногда манера речи, тембр или способ трансляции могут вступать в резонанс с вашим бессознательным, вызывая реакцию сопротивления. Будьте чутки к себе: если инструмент не подходит, отложите его, ведь цель — не само преодоление трудностей восприятия, а тишина и ясность ума.`,
    source: "Хочу Ясности",
