    number: 576,
    text: `В реальности вопросов «почему» и «зачем» не существует. Дерево растет не потому, что у него есть цель, и не потому, что оно выполняет некую задачу. Все причины и следствия — это виртуальный мир концепций, который ум натягивает на реальность, создавая иллюзию объяснения того, что не нуждается в описании.`,
