    text: `Ум создает грандиозные нарративы о спасении миллионов жизней и завершении войн, чтобы укрепить иллюзию 'Я', которое действует в мире. Посмотри, кто этот рассказчик, который присваивает себе время, историю и спасение, оставаясь при этом лишь сгустком мыслей, не имеющим субстанции.`,
