    text: `Выйти за пределы ума невозможно, потому что нет ничего, кроме ума. Мир, который вас окружает — это не набор хаотичных звуков и картинок, а смыслы, которыми является ум. Все, что вы видите, слышите и чувствуете — это и есть ум.`,
